1	// Strict fake DOM + fake fetch for running public/app.js inside a node:vm context.
2	// Every object handed to the page script is a Proxy that records a violation when the
3	// script touches anything outside the API allow-list of the spec.
4	import vm from 'node:vm';
5	import fs from 'node:fs';
6	
7	export const PUBLIC_DIR = '/root/bench-runs/h4-610ab0b5/public/';
8	export const APP_SRC = fs.readFileSync(PUBLIC_DIR + 'app.js', 'utf8');
9	export const HTML_SRC = fs.readFileSync(PUBLIC_DIR + 'index.html', 'utf8');
10	
11	const TAGS = {
12	  'booking-form': 'form', room: 'select', title: 'input', date: 'input', start: 'input',
13	  end: 'input', book: 'button', 'filter-date': 'input', 'show-all': 'button',
14	  'booking-list': 'ul', error: 'p',
15	};
16	const ELEMENT_ALLOWED = new Set([
17	  'textContent', 'value', 'type', 'disabled', 'append', 'replaceChildren', 'addEventListener',
18	]);
19	
20	export class FakeEl {
21	  constructor(tagName, id = '') {
22	    this.tagName = tagName;
23	    this.id = id;
24	    this.children = [];
25	    this.listeners = {};
26	    this.watchers = [];
27	    this.type = '';
28	    this.disabled = false;
29	    this.rawValue = '';
30	    this.valueSet = false;
31	  }
32	
33	  get value() {
34	    if (this.tagName === 'select' && !this.valueSet) {
35	      const first = this.children.find((c) => c.tagName === 'option');
36	      return first ? first.value : '';
37	    }
38	    return this.rawValue;
39	  }
40	
41	  set value(v) {
42	    this.rawValue = String(v);
43	    this.valueSet = true;
44	    this.watchers.forEach((w) => w('value', this.rawValue));
45	  }
46	
47	  get textContent() {
48	    return this.children.map((c) => (c.nodeType === 3 ? c.data : c.textContent)).join('');
49	  }
50	
51	  set textContent(v) {
52	    const text = String(v);
53	    this.children = text === '' ? [] : [{ nodeType: 3, data: text }];
54	    this.watchers.forEach((w) => w('textContent', text));
55	  }
56	
57	  addEventListener(type, fn) {
58	    (this.listeners[type] ||= []).push(fn);
59	  }
60	}
61	
62	function toNode(node, rawOf) {
63	  if (typeof node === 'string') return { nodeType: 3, data: node };
64	  if (node !== null && typeof node === 'object') return rawOf.get(node) ?? node;
65	  return { nodeType: 3, data: String(node) };
66	}
67	
68	function guard(raw, allowed, label, violations, rawOf, ignore = new Set()) {
69	  const proxy = new Proxy(raw, {
70	    get(target, prop) {
71	      if (typeof prop === 'symbol' || ignore.has(prop)) return undefined;
72	      if (!allowed.has(prop)) {
73	        violations.push(`${label}.${prop} (get)`);
74	        return undefined;
75	      }
76	      const v = Reflect.get(target, prop, target);
77	      return typeof v === 'function' ? v.bind(target) : v;
78	    },
79	    set(target, prop, value) {
80	      if (!allowed.has(prop)) violations.push(`${label}.${String(prop)} (set)`);
81	      return Reflect.set(target, prop, value, target);
82	    },
83	    has(target, prop) {
84	      violations.push(`${label}.${String(prop)} (has)`);
85	      return Reflect.has(target, prop);
86	    },
87	  });
88	  rawOf.set(proxy, raw);
89	  return proxy;
90	}
91	
92	function patchContainer(el, rawOf) {
93	  el.append = (...nodes) => { el.children.push(...nodes.map((n) => toNode(n, rawOf))); };
94	  el.replaceChildren = (...nodes) => { el.children = nodes.map((n) => toNode(n, rawOf)); };
95	}
96	
97	function makeReply(spec, violations, rawOf) {
98	  const raw = {
99	    status: spec.status,
100	    json() {
101	      spec.jsonCalls = (spec.jsonCalls || 0) + 1;
102	      if (spec.jsonFn) return spec.jsonFn();
103	      return spec.badJson ? Promise.reject(new Error('bad json')) : Promise.resolve(spec.body);
104	    },
105	  };
106	  return guard(raw, new Set(['status', 'json']), 'reply', violations, rawOf, new Set(['then']));
107	}
108	
109	export function reply(status, body, opts = {}) {
110	  return { status, body, jsonCalls: 0, ...opts };
111	}
112	
113	export const flush = async () => {
114	  for (let i = 0; i < 8; i += 1) await new Promise((r) => setImmediate(r));
115	};
116	
117	export function loadPage(script = () => undefined) {
118	  const violations = [];
119	  const rawOf = new WeakMap();
120	  const els = {};
121	  const proxies = {};
122	  for (const [id, tag] of Object.entries(TAGS)) {
123	    els[id] = new FakeEl(tag, id);
124	    patchContainer(els[id], rawOf);
125	    proxies[id] = guard(els[id], ELEMENT_ALLOWED, `#${id}`, violations, rawOf);
126	  }
127	  const calls = [];
128	  const create = (tag) => {
129	    const el = new FakeEl(tag);
130	    patchContainer(el, rawOf);
131	    return guard(el, ELEMENT_ALLOWED, `<${tag}>`, violations, rawOf);
132	  };
133	  const document = guard({
134	    getElementById: (id) => proxies[id] ?? null,
135	    createElement: create,
136	  }, new Set(['getElementById', 'createElement']), 'document', violations, rawOf);
137	  const fetch = (url, options) => {
138	    const call = { index: calls.length, url, options, bookDisabled: els.book.disabled };
139	    calls.push(call);
140	    return new Promise((resolve, reject) => {
141	      call.resolve = (spec) => resolve(makeReply(spec, violations, rawOf));
142	      call.reject = (err = new TypeError('network down')) => reject(err);
143	      const auto = script(call);
144	      if (auto === 'reject') call.reject();
145	      else if (auto) call.resolve(auto);
146	    });
147	  };
148	  const context = vm.createContext({ document, fetch });
149	  const h = { els, calls, violations, context, listeners: {} };
150	  h.run = () => vm.runInContext(APP_SRC, context, { filename: 'app.js' });
151	  h.dispatch = (el, type, extras = {}) => dispatch(el, type, extras, violations, rawOf);
152	  h.respond = (i, spec) => calls[i].resolve(spec);
153	  h.fail = (i) => calls[i].reject();
154	  h.urls = () => calls.map((c) => c.url);
155	  return h;
156	}
157	
158	function dispatch(el, type, extras, violations, rawOf) {
159	  const rawEvent = { ...extras, prevented: false, preventDefault() { rawEvent.prevented = true; } };
160	  const ev = guard(rawEvent, new Set(['preventDefault']), 'event', violations, rawOf);
161	  const fns = el.listeners[type] || [];
162	  fns.forEach((fn) => fn(ev));
163	  return { prevented: rawEvent.prevented, listenerCount: fns.length };
164	}
