76	test('stdout holds only the listening line, even after errors and a 500', async (t) => {
77	  const dir = await tmp(t);
78	  const server = await boot(t, { cwd: dir, env: { DATA_FILE: 'missing/data.json' } });
79	  await request(server.port, { path: '/api/rooms' });
