9	const JSON_HDR = { 'Content-Type': 'application/json' };
10	const MSG = {
11	  type: 'content type must be application/json',
12	  large: 'body too large',
13	  obj: 'body must be a JSON object',
14	  room: 'room must be one of Aurora, Borealis, Cosmos',
15	  title: 'title must be 1 to 80 characters',
16	  date: 'date must be a valid YYYY-MM-DD date',
17	  start: 'start must be HH:MM',
18	  end: 'end must be HH:MM',
