22	function useServer(ctx) {
23	  before(async () => {
24	    ctx.dir = await makeTempDir();
25	    ctx.srv = await startServer({ cwd: ctx.dir, env: { DATA_FILE: join(ctx.dir, 'data.json') } });
26	    ctx.port = ctx.srv.port;
27	  });
