40	const listAll = async (port) => (await request(port, { path: '/api/bookings' })).json().bookings;
41	
42	// A distinct (date) per call so successful bookings never collide with each other.
43	let counter = 0;
44	function fresh(overrides = {}) {
45	  const n = counter++;
46	  const month = String(1 + Math.floor(n / 28)).padStart(2, '0');
47	  const day = String(1 + (n % 28)).padStart(2, '0');
48	  return { ...B, date: `2030-${month}-${day}`, ...overrides };
49	}
50	
51	function padTo(text, size) {
52	  return text + ' '.repeat(size - Buffer.byteLength(text));
53	}
54	
55	function postChunked(port, chunks, headers = JSON_HDR) {
56	  return new Promise((resolve, reject) => {
57	    const req = http.request({ host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', headers, agent: false }, (res) => {
58	      const parts = [];
59	      res.on('data', (c) => parts.push(c));
60	      res.on('end', () => {
61	        const text = Buffer.concat(parts).toString('utf8');
62	        resolve({ status: res.statusCode, headers: res.headers, text, json: () => JSON.parse(text) });
63	      });
64	    });
65	    req.on('error', reject);
66	    for (const chunk of chunks) req.write(chunk);
67	    req.end();
68	  });
69	}
