72	function rejectionCases(ctx, cases, status, message, headers = JSON_HDR) {
73	  for (const [label, body] of cases) {
74	    it(`${status} for ${label}`, async () => {
75	      expectError(await postBooking(ctx.port, body, headers), status, message);
76	    });
77	  }
78	}
